content:
Below is a reusable Pulumi `ComponentResource` that creates:

- A private, versioned, encrypted S3 bucket
- Production cross-region replication to `us-west-2`
- A private RDS PostgreSQL instance with deletion protection and backups
- A least-privilege IAM role using EKS OIDC/IRSA
- A secret database connection string stored as a Pulumi secret

The EKS cluster, Kubernetes service account, and HTTPS exposure remain outside the component. Their networking and OIDC outputs are passed into it.

## Project structure

```text
.
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── package.json
├── tsconfig.json
├── index.ts
└── service-infrastructure.ts
```

## `service-infrastructure.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export type Environment = "dev" | "prod";

export interface ServiceInfrastructureArgs {
    environment: Environment;

    /**
     * Private subnet IDs in which RDS will be deployed.
     * Supply subnets from at least two availability zones.
     */
    databaseSubnetIds: pulumi.Input<pulumi.Input<string>[]>;

    /**
     * VPC containing the database and application.
     */
    vpcId: pulumi.Input<string>;

    /**
     * Security group attached to the application/EKS workloads.
     * PostgreSQL ingress is allowed only from this security group.
     */
    applicationSecurityGroupId: pulumi.Input<string>;

    /**
     * EKS OIDC provider information used for IRSA.
     */
    oidcProviderArn: pulumi.Input<string>;
    oidcProviderUrl: pulumi.Input<string>;

    kubernetesNamespace: pulumi.Input<string>;
    kubernetesServiceAccount: pulumi.Input<string>;

    databaseName?: pulumi.Input<string>;
    databaseUsername?: pulumi.Input<string>;

    /**
     * Must be supplied using Config.requireSecret or another secret Output.
     */
    databasePassword: pulumi.Input<string>;

    tags?: pulumi.Input<Record<string, pulumi.Input<string>>>;
}

export class ServiceInfrastructure extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly database: aws.rds.Instance;
    public readonly serviceAccountRole: aws.iam.Role;

    public readonly bucketName: pulumi.Output<string>;
    public readonly databaseEndpoint: pulumi.Output<string>;
    public readonly databaseConnectionString: pulumi.Output<string>;
    public readonly serviceAccountRoleArn: pulumi.Output<string>;

    constructor(
        name: string,
        args: ServiceInfrastructureArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("example:platform:ServiceInfrastructure", name, {}, opts);

        const childOpts: pulumi.ResourceOptions = { parent: this };

        const defaultTags: Record<string, pulumi.Input<string>> = {
            Component: name,
            Environment: args.environment,
            ManagedBy: "Pulumi",
        };

        const tags = pulumi
            .output(args.tags ?? {})
            .apply(customTags => ({
                ...defaultTags,
                ...customTags,
            }));

        /*
         * Application assets bucket
         */
        this.bucket = new aws.s3.BucketV2(
            `${name}-assets`,
            {
                forceDestroy: args.environment === "dev",
                tags,
            },
            childOpts,
        );

        new aws.s3.BucketVersioningV2(
            `${name}-assets-versioning`,
            {
                bucket: this.bucket.id,
                versioningConfiguration: {
                    status: "Enabled",
                },
            },
            childOpts,
        );

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-encryption`,
            {
                bucket: this.bucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                    bucketKeyEnabled: true,
                }],
            },
            childOpts,
        );

        new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-public-access-block`,
            {
                bucket: this.bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            childOpts,
        );

        /*
         * Least-privilege IRSA role.
         */
        const oidcIssuer = pulumi
            .output(args.oidcProviderUrl)
            .apply(url => url.replace(/^https:\/\//, "").replace(/\/$/, ""));

        const assumeRolePolicy = pulumi
            .all([
                args.oidcProviderArn,
                oidcIssuer,
                args.kubernetesNamespace,
                args.kubernetesServiceAccount,
            ])
            .apply(([providerArn, issuer, namespace, serviceAccount]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: {
                            Federated: providerArn,
                        },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                [`${issuer}:aud`]: "sts.amazonaws.com",
                                [`${issuer}:sub`]:
                                    `system:serviceaccount:${namespace}:${serviceAccount}`,
                            },
                        },
                    }],
                }),
            );

        this.serviceAccountRole = new aws.iam.Role(
            `${name}-service-account`,
            {
                assumeRolePolicy,
                description: `IRSA role for ${name} ${args.environment}`,
                tags,
            },
            childOpts,
        );

        const applicationBucketPolicy = pulumi
            .all([this.bucket.arn])
            .apply(([bucketArn]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Sid: "ListApplicationBucket",
                            Effect: "Allow",
                            Action: ["s3:ListBucket"],
                            Resource: bucketArn,
                        },
                        {
                            Sid: "ReadWriteApplicationObjects",
                            Effect: "Allow",
                            Action: [
                                "s3:GetObject",
                                "s3:GetObjectVersion",
                                "s3:PutObject",
                                "s3:DeleteObject",
                            ],
                            Resource: `${bucketArn}/*`,
                        },
                    ],
                }),
            );

        new aws.iam.RolePolicy(
            `${name}-service-account-assets`,
            {
                role: this.serviceAccountRole.id,
                policy: applicationBucketPolicy,
            },
            childOpts,
        );

        /*
         * Production cross-region S3 replication.
         */
        if (args.environment === "prod") {
            const replicationProvider = new aws.Provider(
                `${name}-replication-provider`,
                {
                    region: "us-west-2",
                },
                { parent: this },
            );

            const replicaBucket = new aws.s3.BucketV2(
                `${name}-assets-replica`,
                {
                    tags: pulumi.output(tags).apply(t => ({
                        ...t,
                        Purpose: "Cross-region replication destination",
                    })),
                },
                {
                    parent: this,
                    provider: replicationProvider,
                },
            );

            const replicaVersioning = new aws.s3.BucketVersioningV2(
                `${name}-assets-replica-versioning`,
                {
                    bucket: replicaBucket.id,
                    versioningConfiguration: {
                        status: "Enabled",
                    },
                },
                {
                    parent: this,
                    provider: replicationProvider,
                },
            );

            new aws.s3.BucketServerSideEncryptionConfigurationV2(
                `${name}-assets-replica-encryption`,
                {
                    bucket: replicaBucket.id,
                    rules: [{
                        applyServerSideEncryptionByDefault: {
                            sseAlgorithm: "AES256",
                        },
                        bucketKeyEnabled: true,
                    }],
                },
                {
                    parent: this,
                    provider: replicationProvider,
                },
            );

            new aws.s3.BucketPublicAccessBlock(
                `${name}-assets-replica-public-access-block`,
                {
                    bucket: replicaBucket.id,
                    blockPublicAcls: true,
                    blockPublicPolicy: true,
                    ignorePublicAcls: true,
                    restrictPublicBuckets: true,
                },
                {
                    parent: this,
                    provider: replicationProvider,
                },
            );

            const replicationRole = new aws.iam.Role(
                `${name}-replication-role`,
                {
                    assumeRolePolicy: aws.iam.assumeRolePolicyForPrincipal({
                        Service: "s3.amazonaws.com",
                    }),
                    tags,
                },
                childOpts,
            );

            const replicationPolicy = pulumi
                .all([this.bucket.arn, replicaBucket.arn])
                .apply(([sourceArn, destinationArn]) =>
                    JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [
                            {
                                Sid: "ReadSourceBucketVersioning",
                                Effect: "Allow",
                                Action: [
                                    "s3:GetReplicationConfiguration",
                                    "s3:ListBucket",
                                ],
                                Resource: sourceArn,
                            },
                            {
                                Sid: "ReadSourceObjectVersions",
                                Effect: "Allow",
                                Action: [
                                    "s3:GetObjectVersion",
                                    "s3:GetObjectVersionAcl",
                                    "s3:GetObjectVersionTagging",
                                ],
                                Resource: `${sourceArn}/*`,
                            },
                            {
                                Sid: "ReplicateToDestination",
                                Effect: "Allow",
                                Action: [
                                    "s3:ReplicateObject",
                                    "s3:ReplicateDelete",
                                    "s3:ReplicateTags",
                                ],
                                Resource: `${destinationArn}/*`,
                            },
                        ],
                    }),
                );

            new aws.iam.RolePolicy(
                `${name}-replication-policy`,
                {
                    role: replicationRole.id,
                    policy: replicationPolicy,
                },
                childOpts,
            );

            new aws.s3.BucketReplicationConfigurationV2(
                `${name}-assets-replication`,
                {
                    bucket: this.bucket.id,
                    role: replicationRole.arn,
                    rules: [{
                        id: "replicate-all",
                        status: "Enabled",
                        priority: 1,
                        filter: {},
                        deleteMarkerReplication: {
                            status: "Enabled",
                        },
                        destination: {
                            bucket: replicaBucket.arn,
                            storageClass: "STANDARD",
                        },
                    }],
                },
                {
                    parent: this,
                    dependsOn: [replicaVersioning],
                },
            );
        }

        /*
         * PostgreSQL database
         */
        const databaseSecurityGroup = new aws.ec2.SecurityGroup(
            `${name}-database`,
            {
                vpcId: args.vpcId,
                description: `PostgreSQL access for ${name}`,
                ingress: [{
                    protocol: "tcp",
                    fromPort: 5432,
                    toPort: 5432,
                    securityGroups: [args.applicationSecurityGroupId],
                    description: "PostgreSQL from application workloads",
                }],
                egress: [{
                    protocol: "-1",
                    fromPort: 0,
                    toPort: 0,
                    cidrBlocks: ["0.0.0.0/0"],
                    description: "Outbound connectivity",
                }],
                tags,
            },
            childOpts,
        );

        const databaseSubnetGroup = new aws.rds.SubnetGroup(
            `${name}-database`,
            {
                subnetIds: args.databaseSubnetIds,
                tags,
            },
            childOpts,
        );

        this.database = new aws.rds.Instance(
            `${name}-postgres`,
            {
                engine: "postgres",
                engineVersion: "16",
                instanceClass:
                    args.environment === "prod"
                        ? "db.t3.medium"
                        : "db.t3.micro",

                allocatedStorage: args.environment === "prod" ? 100 : 20,
                maxAllocatedStorage: args.environment === "prod" ? 500 : 100,
                storageType: "gp3",
                storageEncrypted: true,

                dbName: args.databaseName ?? "application",
                username: args.databaseUsername ?? "application",
                password: pulumi.secret(args.databasePassword),
                port: 5432,

                multiAz: args.environment === "prod",
                publiclyAccessible: false,

                dbSubnetGroupName: databaseSubnetGroup.name,
                vpcSecurityGroupIds: [databaseSecurityGroup.id],

                deletionProtection: true,
                backupRetentionPeriod: args.environment === "prod" ? 30 : 7,
                copyTagsToSnapshot: true,

                autoMinorVersionUpgrade: true,
                applyImmediately: args.environment === "dev",

                skipFinalSnapshot: args.environment === "dev",
                finalSnapshotIdentifier:
                    args.environment === "prod"
                        ? `${name}-postgres-final`
                        : undefined,

                tags,
            },
            {
                parent: this,

                // Prevent accidental Pulumi deletion in addition to RDS
                // deletion protection. Remove deliberately before teardown.
                protect: true,
            },
        );

        this.bucketName = this.bucket.bucket;
        this.databaseEndpoint = this.database.endpoint;
        this.serviceAccountRoleArn = this.serviceAccountRole.arn;

        this.databaseConnectionString = pulumi.secret(
            pulumi
                .all([
                    args.databaseUsername ?? "application",
                    args.databasePassword,
                    this.database.address,
                    this.database.port,
                    args.databaseName ?? "application",
                ])
                .apply(([username, password, host, port, databaseName]) =>
                    `postgresql://${encodeURIComponent(username)}:${encodeURIComponent(
                        password,
                    )}@${host}:${port}/${encodeURIComponent(databaseName)}?sslmode=require`,
                ),
        );

        this.registerOutputs({
            bucketName: this.bucketName,
            databaseEndpoint: this.databaseEndpoint,
            databaseConnectionString: this.databaseConnectionString,
            serviceAccountRoleArn: this.serviceAccountRoleArn,
        });
    }
}
```

## `index.ts`

This example reads environment-specific values from the active Pulumi stack. Network and OIDC values can also come directly from an EKS component instead of configuration.

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ServiceInfrastructure, Environment } from "./service-infrastructure";

const config = new pulumi.Config();

const environment = config.require("environment") as Environment;

if (environment !== "dev" && environment !== "prod") {
    throw new Error(`environment must be "dev" or "prod", got "${environment}"`);
}

const infrastructure = new ServiceInfrastructure("webapp", {
    environment,

    vpcId: config.require("vpcId"),
    databaseSubnetIds: config.requireObject<string[]>("databaseSubnetIds"),
    applicationSecurityGroupId: config.require("applicationSecurityGroupId"),

    oidcProviderArn: config.require("oidcProviderArn"),
    oidcProviderUrl: config.require("oidcProviderUrl"),
    kubernetesNamespace: config.get("kubernetesNamespace") ?? "webapp",
    kubernetesServiceAccount:
        config.get("kubernetesServiceAccount") ?? "webapp",

    databaseName: config.get("databaseName") ?? "webapp",
    databaseUsername: config.get("databaseUsername") ?? "webapp",
    databasePassword: config.requireSecret("databasePassword"),

    tags: {
        Application: "webapp",
        Owner: "platform-team",
    },
});

export const assetsBucketName = infrastructure.bucketName;
export const databaseEndpoint = infrastructure.databaseEndpoint;
export const databaseConnectionString =
    infrastructure.databaseConnectionString;
export const serviceAccountRoleArn =
    infrastructure.serviceAccountRoleArn;
```

## `Pulumi.yaml`

```yaml
name: webapp-infrastructure
runtime:
  name: nodejs
  options:
    typescript: true
description: Web application service infrastructure
```

## `Pulumi.dev.yaml`

Resource IDs shown here are examples and should be replaced with outputs from the dev network/EKS stack.

```yaml
config:
  aws:region: us-east-1

  webapp-infrastructure:environment: dev
  webapp-infrastructure:vpcId: vpc-dev-example
  webapp-infrastructure:databaseSubnetIds:
    - subnet-dev-private-a
    - subnet-dev-private-b
  webapp-infrastructure:applicationSecurityGroupId: sg-dev-application

  webapp-infrastructure:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE
  webapp-infrastructure:oidcProviderUrl: https://oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE
  webapp-infrastructure:kubernetesNamespace: webapp
  webapp-infrastructure:kubernetesServiceAccount: webapp
  webapp-infrastructure:databaseName: webapp
  webapp-infrastructure:databaseUsername: webapp
```

## `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1

  webapp-infrastructure:environment: prod
  webapp-infrastructure:vpcId: vpc-prod-example
  webapp-infrastructure:databaseSubnetIds:
    - subnet-prod-private-a
    - subnet-prod-private-b
  webapp-infrastructure:applicationSecurityGroupId: sg-prod-application

  webapp-infrastructure:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/PRODEXAMPLE
  webapp-infrastructure:oidcProviderUrl: https://oidc.eks.us-east-1.amazonaws.com/id/PRODEXAMPLE
  webapp-infrastructure:kubernetesNamespace: webapp
  webapp-infrastructure:kubernetesServiceAccount: webapp
  webapp-infrastructure:databaseName: webapp
  webapp-infrastructure:databaseUsername: webapp
```

Do not put the database password directly in either YAML file. Set it through Pulumi’s encrypted stack configuration:

```bash
pulumi stack init dev
pulumi config set --secret databasePassword 'development-password'
```

```bash
pulumi stack init prod
pulumi config set --secret databasePassword 'production-password'
```

This writes encrypted ciphertext into the stack configuration and marks the derived connection-string output as secret.

